            if (i,j) in seen: continue
            B=[(i,j)]; q=deque([(i,j)]); seen.add((i,j))
            while q:
                a,b=q.popleft()
                for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                    c,d=a+da,b+db
                    if 0<=c<H and 0<=d<W and inp[c][d]!=bg and (c,d) not in seen:
                        seen.add((c,d)); B.append((c,d)); q.append((c,d))
            blocks.append(B)
    P=max(blocks,key=len)
    out=[r[:] for r in inp]
    # pattern translation anchored at top-left of each marker cluster? markers are single cells here.
